\documentclass{article}
\usepackage{fontspec}
\setmainfont{Arial}
\begin{document}

\section*{প্রধান}
\begin{itemize}
    \item পামেলা দশা
    \item ওয়াটার ব্লুম
    \item সিনোসাইট
    \item মিথোজীবিতা
\end{itemize}

পরিচিত। এদের অসবুজ দেখে ক্লোরোফিল থাকে না, তাই সালোকসংশ্লেষণ প্রক্রিয়া খাদ্য প্রস্তুত করতে পারে না। একারণে এরা মৃতজীবী বা পরজীবী হিসেবে বা কোনো কোনো ক্ষেত্রে মিথোজীবী হিসেবে জীবন যাপন করে। জীববিজ্ঞানের যে শাখায় ছত্রাক নিয়ে গবেষণা ও আলোচনা করা হয় তাকে ছত্রাকবিজ্ঞান (mycology) বলে। অধিকাংশ শৈবাল আণুবীক্ষণিক, তাই খালি চোখে দেখা যায় না। কিন্তু পরিষ্কার পানিতে এদের উপস্থিতি চোখে না পড়লেও বায়ুমণ্ডলের ৭০% অক্সিজেন এরা যোগান দেয়। অপরদিকে, ছত্রাক মৃত জীবদেহের উপর জন্মে দৈব উপাদান ভেঙ্গে মাটিকে উর্বর করে তোলে। এজন্য শৈবাল ও ছত্রাক গ্রুপ দুটি আমাদের নিকট বিশেষ গুরুত্বপূর্ণ।

\section*{এ অধ্যায়ের পাঠগুলো পড়ে যা যা শিখব}
